package com.sobrenaturaldirector.derivation;
import java.util.*; import com.sobrenaturaldirector.model.player.PlayerModel; import com.sobrenaturaldirector.model.world.WorldModel; import com.sobrenaturaldirector.observation.model.*;
public final class ObservationDerivationPipeline { private final PlayerModelDeriver players=new PlayerModelDeriver();private final WorldModelDeriver worlds=new WorldModelDeriver();public DerivedModels derive(ObservationFrame f){List<PlayerModel>p=new ArrayList<PlayerModel>();List<WorldModel>w=new ArrayList<WorldModel>();List<DerivedSignal>s=new ArrayList<DerivedSignal>();boolean partial=f.getDiagnostics().getStatus()!=ObservationStatus.COMPLETE;for(WorldSnapshot x:f.getWorlds())w.add(worlds.derive(x,f.getDiagnostics().getStatus()));for(PlayerSnapshot x:f.getPlayers()){PlayerDerivation d=players.derive(x,partial);p.add(d.getModel());s.addAll(d.getTrace().getSignals());}return new DerivedModels(p,w,new DerivationTrace(s,partial?Collections.singletonList("DERIVATION_INPUT_PARTIAL"):Collections.<String>emptyList()));} }
